# Now, let's identify which songs in each playlist are "old songs" (i.e., their song_id is in our old_song_to_spotify_id mapping).
# We'll build a mapping: playlist_id -> list of old song_ids to remove from that playlist.

old_song_ids = set(song["spotify_song_id"] for song in json_friendly_mapping)
songs_to_remove = {}

for playlist_id, song_ids in playlist_tracks.items():
    to_remove = [song_id for song_id in song_ids if song_id in old_song_ids]
    if to_remove:
        songs_to_remove[playlist_id] = to_remove

print(songs_to_remove)

# Now, let's collect all the old song Spotify IDs into a set for fast lookup.
old_song_ids = set(song["spotify_song_id"] for song in json_friendly_mapping)

# For each playlist, find which old song IDs are present.
# We'll build a mapping: playlist_id -> list of old song IDs to remove from that playlist.
playlist_old_songs_to_remove = {}
for playlist_id, song_ids in playlist_tracks.items():
    to_remove = [song_id for song_id in song_ids if song_id in old_song_ids]
    if to_remove:
        playlist_old_songs_to_remove[playlist_id] = to_remove

print(playlist_old_songs_to_remove)

