steps.code:
# Now, let's fetch the metadata for each song_id in unique_song_ids using the show_song API.
# We'll store the mapping from song_id to (title, artist) for later matching.
# To avoid hitting any rate limits, let's process them in batches of 10.

song_id_to_metadata = {}
batch_size = 10

for i in range(0, len(unique_song_ids), batch_size):
    batch = unique_song_ids[i:i+batch_size]
    for song_id in batch:
        song_info = apis.spotify.show_song(song_id=song_id)
        if "title" in song_info and "artists" in song_info and song_info["artists"]:
            artist_name = song_info["artists"][0]["name"]
            song_id_to_metadata[song_id] = {
                "title": song_info["title"],
                "artist": artist_name
            }
        else:
            song_id_to_metadata[song_id] = None  # In case of failure

print(song_id_to_metadata)

