steps.code:
# To map the song titles from songs_to_archive to Spotify song IDs, I need to get the title for each song_id in unique_song_ids and match it to the archive list.
# Let's fetch the song details for all unique_song_ids and build a mapping from title to song_id.

spotify_song_id_to_title = {}
for song_id in unique_song_ids:
    song_details = apis.spotify.show_song(song_id=song_id)
    if isinstance(song_details, dict) and "title" in song_details:
        spotify_song_id_to_title[song_details["title"].strip().lower()] = song_id

# Now, let's map the songs_to_archive (by title, case-insensitive) to their corresponding Spotify song IDs.
archive_song_ids = []
for song_title in songs_to_archive:
    song_id = spotify_song_id_to_title.get(song_title.strip().lower())
    if song_id is not None:
        archive_song_ids.append(song_id)

print(archive_song_ids)  # These are the Spotify song IDs to remove from playlists and add to "Old Songs"

