# Now, let's remove all the songs in songs_to_archive_ids from all playlists.
# We'll skip the "Old Songs" playlist (id=654) to avoid removing from the archive itself.
# We'll collect the results for each removal.

removal_results = []
for playlist in all_playlists:
    playlist_id = playlist["playlist_id"]
    if playlist_id == old_songs_playlist_id:
        continue  # skip "Old Songs"
    for song_id in songs_to_archive_ids:
        result = apis.spotify.remove_song_from_playlist(
            playlist_id=playlist_id,
            song_id=song_id,
            access_token=spotify_access_token
        )
        removal_results.append({
            "playlist_id": playlist_id,
            "song_id": song_id,
            "result": result
        })

print(removal_results)

# Some songs in songs_to_archive_ids are not present in every playlist, which causes a 422 error.
# To avoid this, let's first check which songs are actually present in each playlist before attempting to remove them.
# We'll build a mapping of playlist_id -> set of song_ids in that playlist, then only remove if present.

playlist_songs_map = {}
for playlist in all_playlists:
    playlist_id = playlist["playlist_id"]
    # Each playlist object should have a list of song_ids, let's check the structure
    playlist_songs_map[playlist_id] = set(playlist.get("song_ids", []))

removal_results = []
for playlist in all_playlists:
    playlist_id = playlist["playlist_id"]
    if playlist_id == old_songs_playlist_id:
        continue  # skip "Old Songs"
    songs_in_playlist = playlist_songs_map[playlist_id]
    for song_id in songs_to_archive_ids:
        if song_id in songs_in_playlist:
            result = apis.spotify.remove_song_from_playlist(
                playlist_id=playlist_id,
                song_id=song_id,
                access_token=spotify_access_token
            )
