# Now, let's match the parsed old songs list (song_artist_list) to the songs in the playlists.
# We'll match by both title (case-insensitive, stripped) and all artist names (set equality, case-insensitive).
# We'll collect the song_ids that match the old songs list.

def normalize(s):
    return s.strip().lower()

old_song_keys = set(
    (normalize(title), frozenset(normalize(a) for a in artists))
    for title, artists in song_artist_list
)

old_song_ids = []
for song_id, info in song_id_to_info.items():
    key = (normalize(info["title"]), frozenset(normalize(a) for a in info["artists"]))
    if key in old_song_keys:
        old_song_ids.append(song_id)

print(old_song_ids)  # These are the song_ids to remove and archive.

