# The top result matches the song title and artist exactly: "Tangled Lies" by "Ava Morgan".
# The release_date is "2022-12-11T06:22:44". The release month is December 2022.
# Let's write a function to do this for all entries, extracting the release month and year for each.

from datetime import datetime

def get_release_month_from_results(song_title, artists, results):
    # Try to find the best match by title and all artists
    for result in results:
        if result['title'].lower() == song_title.lower():
            result_artists = set(a['name'].lower() for a in result['artists'])
            if all(artist.lower() in result_artists for artist in artists):
                dt = datetime.fromisoformat(result['release_date'])
                return dt.strftime('%B %Y')
    # Fallback: just use the first result
    if results:
        dt = datetime.fromisoformat(results[0]['release_date'])
        return dt.strftime('%B %Y')
    return None

# Now, let's search for all songs and collect their release months.
release_months = []
for entry in todo_entries_missing_release:
    query = f"{entry['song']} {' '.join(entry['artists'])}"
    results = apis.spotify.search_songs(query=query, page_limit=5)
    release_month = get_release_month_from_results(entry['song'], entry['artists'], results)
    release_months.append(release_month)

# Show the first few release months to verify.
print(release_months[:5])

