    match = None
    for result in results:
        if result["title"].lower() == song["title"].lower():
            result_artist_names = {a["name"].lower() for a in result["artists"]}
            song_artist_names = {a.lower() for a in song["artists"]}
            if result_artist_names & song_artist_names:
                match = result
                break
    if match and "release_date" in match:
